//
pub const MC_CMD_MAC_STATISTICS_DESCRIPTOR_IN_OFFSET_OFST: c_int = 4;
pub const MC_CMD_MAC_STATISTICS_DESCRIPTOR_IN_OFFSET_LEN: c_int = 4;
